import React, { useState } from 'react';
import { Layout, Menu, Space, Drawer, Button } from 'antd';
import { PhoneTwoTone, MailTwoTone, MenuOutlined } from '@ant-design/icons';
import logo from '../img/ccc_main_2.png';
import '../App.css';

const { Header } = Layout;

const HeaderMobile = ({ menuItems }) => {
  const [drawerVisible, setDrawerVisible] = useState(false);
  const openDrawer = () => setDrawerVisible(true);
  const closeDrawer = () => setDrawerVisible(false);

  return (
    <>
      <Header className="mobile-header contact-info-mobile"
        style={{
          top: 0,
          zIndex: 1000,
          alignItems: 'center',
          padding: '0 10px'
        }}
      >
        <Space>
          <PhoneTwoTone twoToneColor="#015BBB" />
          <span>01234567890</span>
          <MailTwoTone twoToneColor="#015BBB" />
          <span>info@cozycornercare.com</span>
        </Space>
      </Header>
      
      <Header className="mobile-header"
        style={{
          top: 40, // offset this header below the contact info header
          zIndex: 999,
          display: 'flex',
          alignItems: 'center',
          padding: '0 10px',
        }}
      >
        <img
          src={logo}
          alt="Logo"
          style={{
            height: '10em', // smaller for mobile
            width: '16em',
            objectFit: 'contain',
            marginLeft: '10px',
            marginRight: '10px',
            marginTop: '2px',
          }}
        />
        <Button
          type="text"
          icon={<MenuOutlined style={{ fontSize: '24px', color: '#015BBB' }} />}
          onClick={openDrawer}
          style={{ marginLeft: 'auto' }}
        />
        <Drawer
          title="Menu"
          placement="right"
          onClose={closeDrawer}
          open={drawerVisible}
        >
          <Menu
            mode="vertical"
            defaultSelectedKeys={['home']}
            items={menuItems}
            onClick={closeDrawer}
          />
        </Drawer>
      </Header>
    </>
  );
};

export default HeaderMobile;
